define <vscale x 2 x float> @ld1_nxv2f32(ptr %addr, i64 %off) {
  %ptr = getelementptr inbounds float, ptr %addr, i64 %off
  %val = load volatile <vscale x 2 x float>, ptr %ptr, align 8
  ret <vscale x 2 x float> %val
}

